    let forResource (resourceType: string) =
        all |> List.filter (fun p -> p.ResourceType = resourceType)

    let tryFind (resourceType: string) (code: string) =
        all |> List.tryFind (fun p -> p.ResourceType = resourceType && p.Code = code)
